// Regenerate the strict-live production schema from the local development schema.
//
//   Run from the repository root:
//     node scripts/generate-production-schema.mjs
//
// The local source (database/schema.sql) intentionally carries local-only seed
// fixtures. The generated file keeps DDL only: CREATE TABLE IF NOT EXISTS,
// indexes, keys and constraints. All data-bearing statements and seed comments
// are stripped. Incremental DDL lives in database/migrations/*.sql and is
// applied separately by `node scripts/db.js setup-production`.
//
// The generator refuses to write output that still contains a data-bearing
// statement (INSERT/REPLACE/TRUNCATE/DELETE/UPDATE/DROP/CREATE DATABASE/USE,
// or SET @). Referential actions (ON DELETE/ON UPDATE) are allowed in DDL.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const sourcePath = join(root, 'database', 'schema.sql');
const outputPath = join(root, 'database', 'schema-production.sql');
const source = readFileSync(sourcePath, 'utf8');

const header = `-- ============================================================================
-- CHSC production schema — strict live data, idempotent, non-destructive
-- Generated by scripts/generate-production-schema.mjs from database/schema.sql.
-- Data-free bootstrap. DDL only: CREATE TABLE IF NOT EXISTS, indexes, keys and
-- constraints. No data-modification or database-selection statements.
-- Migrations in database/migrations/*.sql are applied separately by
-- \`node scripts/db.js setup-production\`. No fixture accounts or sample records.
-- Regenerate: node scripts/generate-production-schema.mjs
-- ============================================================================

`;

// The local fixture block begins at the SEED DATA banner. Everything from that
// banner onward (hashes, sample rows, AUTO_INCREMENT bumps, sample queries) is
// local-only and never belongs in a production bootstrap file.
const seedMarker = source.search(/^\s*--\s*SEED DATA\b/im);
if (seedMarker < 0) {
  throw new Error(
    'Could not find the SEED DATA banner in database/schema.sql; refusing to generate a production schema from an unrecognised source.',
  );
}

const ddl = source
  .slice(0, seedMarker)
  .replace(/^\s*CREATE\s+DATABASE[\s\S]*?;/gim, '')
  .replace(/^\s*USE\s+[^;]+;\s*$/gim, '')
  .replace(/^\s*SET\s+FOREIGN_KEY_CHECKS\s*=\s*[01];\s*$/gim, '')
  .replace(/^\s*SET\s+@[A-Za-z0-9_]+\s*=.*;\s*$/gim, '')
  .replace(/^\s*DROP\s+(?:TABLE|DATABASE)[^;]*;\s*$/gim, '')
  .replace(/\bCREATE\s+TABLE\s+(?!IF\s+NOT\s+EXISTS\b)/gi, 'CREATE TABLE IF NOT EXISTS ')
  .split(/\r?\n/)
  .filter((line) => !/^\s*--.*\b(seed|seeded|demo|sample|simulat)\b/i.test(line))
  .filter((line) => !/^\s*--\s*Run:\s*$/i.test(line))
  .filter((line) => !/^\s*--\s*mysql\s+-u\s+root\s+-p\s*<\s*database\/schema\.sql\s*$/i.test(line))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trimEnd();

const output = `${header}${ddl}\n`;

// Guard: scan the final output with SQL comments removed, so explanatory
// comments cannot mask a real data-bearing statement. Referential actions are
// valid DDL, so `ON DELETE` / `ON UPDATE` are normalized before the keyword scan.
const scannable = output
  .replace(/--[^\r\n]*/g, '')
  .replace(/\/\*[\s\S]*?\*\//g, '')
  .replace(/\bON\s+(?:DELETE|UPDATE)\b/gi, 'ON REFERENTIAL_ACTION');
const forbidden = /\b(?:INSERT|REPLACE|TRUNCATE|DELETE|DROP|USE|UPDATE|CREATE\s+DATABASE)\b|\bSET\s+@|\bALTER\s+TABLE\s+[`"]?[\w-]+[`"]?\s+AUTO_INCREMENT\b/gi;
const findings = [...scannable.matchAll(forbidden)].map((match) => match[0].trim());
if (findings.length) {
  throw new Error(
    `Refusing to write ${relative(root, outputPath)}: generated output still contains data-bearing statements: ${[...new Set(findings)].join(', ')}`,
  );
}

writeFileSync(outputPath, output);
console.log(`Wrote ${relative(root, outputPath)}`);
console.log('Verified: 0 INSERT/REPLACE/TRUNCATE/DELETE/UPDATE/DROP/CREATE DATABASE/USE/SET @ statements.');
